/** Success payload of `editor current-clip`. */
export interface EditorCurrentClipResult {
    /** 0-based index of the clip within its track. */
    clipIndex: number;
    /** Display name of the clip. */
    clipName: string;
    /** Clip type: `sing`, `instrument`, `genericMidi`, `audio`, or `chord`. */
    clipType: string;
    /** Track default language code (CHN/JPN/ENG/SPA/KOR). Present only for Sing clips. */
    defaultLanguage?: string;
    /** 0-based index of the clip's track in the project. */
    trackIndex: number;
}

/** Success payload of `editor open`. */
export interface EditorOpenResult {
    /** True if the editor window was already visible before this call. */
    wasAlreadyVisible: boolean;
}

/** Success payload of `editor status`. */
export interface EditorStatusResult {
    /** 0-based index of the clip within its track. Present only when the clip is found on a pattern track. */
    clipIndex?: number;
    /** Display name of the current clip. Present only when a clip is loaded. */
    clipName?: string;
    /** UUID (with braces) of the current clip. Present only when a clip is loaded. */
    clipUuid?: string;
    /** Display name of the track's default articulation. Present only for Instrument clips. */
    defaultArticulation?: string;
    /** Track default language as an English full name (e.g. Chinese). Present only for Sing clips. */
    defaultLanguage?: string;
    /** Clip type of the active editor: Sing, Instrument, GenericMidi, Audio, or Chord. Present only when a clip is loaded. */
    editorType?: string;
    /** Whether a pattern editor has valid content loaded. When false, every clip-context field below is absent. */
    isAvailable: boolean;
    /** Whether the editor window is currently shown. */
    isVisible: boolean;
    /** Articulation display names supported by the whole ensemble. Present only for Instrument clips. */
    supportedArticulations?: string[];
    /** Languages supported by the whole choir, as English full names. Present only for Sing clips. */
    supportedLanguages?: string[];
    /** 0-based index of the clip's track. Present only when the track is found in the project. */
    trackIndex?: number;
}

/** Success payload of `editor tick-range`. */
export interface EditorTickRangeResult {
    /** Editor start position in global ticks; the offset for local-to-global conversion. */
    tickBegin: number;
    /** Editor end position in global ticks. Always greater than tickBegin. */
    tickEnd: number;
}

/** The `editor` operations, mirroring the canonical operation tree 1:1. */
export interface EditorOperations {
    /**
     * Read which clip is currently open in the piano-roll editor.
     *
     * Requires the `editor.read` capability.
     */
    currentClip(options?: CallOptions): Promise<EditorCurrentClipResult>;

    /**
     * Open (make visible) the piano-roll editor window.
     *
     * Requires the `editor.write` capability.
     */
    open(options?: MutatingCallOptions): Promise<EditorOpenResult>;

    /**
     * Read editor open/closed state, visibility, and active clip id.
     *
     * Requires the `editor.read` capability.
     */
    status(options?: CallOptions): Promise<EditorStatusResult>;

    /**
     * Read the editor's total tick range (tickBegin / tickEnd).
     *
     * Requires the `editor.read` capability.
     */
    tickRange(options?: CallOptions): Promise<EditorTickRangeResult>;
}

